/**
 * A project: a working tree on local disk plus shared project state. One workspace per repo,
 * app-wide (rings on the same repo share the tree/git/graph; each ring keeps its own viewport).
 * Mirrors `Workspace.swift`.
 */
class Workspace private constructor(
    val repoFullName: String,
    val root: File,
) {
    enum class Phase { DOWNLOADING, READY, FAILED }

    var phase by mutableStateOf(Phase.DOWNLOADING)
    var failure by mutableStateOf<String?>(null)

    val modifiedPaths = mutableStateListOf<String>()
    var syncedSha by mutableStateOf<String?>(null)
    var upstreamAvailable by mutableStateOf(false)
    private var lastUpstreamCheck = 0L

    /** Bumped when the tree is replaced wholesale (a pull); file views key reloads on it. */
    var treeVersion by mutableStateOf(0)

    // Graph cache — loaded in the background so the Graph container never reloads on swipe.
    var graphRows by mutableStateOf<List<GraphRow>?>(null)
    var graphTips by mutableStateOf<Map<String, String>>(emptyMap())
    var graphError by mutableStateOf<String?>(null)
    private var historyStamp: String? = null
    private var historyInFlight = false

    val hasChanges get() = modifiedPaths.isNotEmpty()

    fun markModified(path: String) { if (path !in modifiedPaths) modifiedPaths.add(path) }
    fun clearModified() { modifiedPaths.clear() }
    fun markSynced(sha: String) { syncedSha = sha; upstreamAvailable = false }

    private var fetchInFlight = false

    /** Download + extract the repo tarball into [root]. */
    suspend fun startDownload(token: String?) {
        if (fetchInFlight || phase == Phase.READY) return
        fetchInFlight = true
        phase = Phase.DOWNLOADING
        try {
            withContext(Dispatchers.IO) { fetchAndExtract(token) }
            phase = Phase.READY
            treeVersion++
        } catch (e: Exception) {
            failure = e.message ?: "download failed"
            phase = Phase.FAILED
        } finally {
            fetchInFlight = false
        }
    }

    private fun fetchAndExtract(token: String?) {
        val url = "https://api.github.com/repos/$repoFullName/tarball"
        val bytes = GitHub.getBytes(url, token)
        root.deleteRecursively()
        root.mkdirs()
        // GitHub tarballs put everything under a single top folder; strip it.
        TarGz.extract(bytes, into = root, stripComponents = 1)
    }

    /** Compare the remote head against [syncedSha] (throttled to once a minute). */
    suspend fun refreshUpstream(token: String) {
        val now = System.currentTimeMillis()
        if (now - lastUpstreamCheck < 60_000) return
        lastUpstreamCheck = now
        val head = withContext(Dispatchers.IO) { runCatching { GitHub.remoteHeadSha(repoFullName, token) }.getOrNull() } ?: return
        upstreamAvailable = head != syncedSha
    }

    /** Keep the commit graph warm; deduped by (treeVersion, syncedSha). */
    suspend fun refreshHistory(token: String) {
        val stamp = "$treeVersion|${syncedSha ?: "?"}"
        if (historyInFlight) return
        if (historyStamp == stamp && graphRows != null) return
        historyInFlight = true
        try {
            val history = withContext(Dispatchers.IO) { GitGraph.fetchHistory(repoFullName, token) }
            graphRows = GitGraph.layout(history.commits)
            graphTips = history.branchTips
            graphError = null
            historyStamp = stamp
        } catch (e: Exception) {
            if (graphRows == null) graphError = e.message ?: "history failed"
        } finally {
            historyInFlight = false
        }

