            x[9] ^= rotate(x[5] &+ x[1], 7);    x[13] ^= rotate(x[9] &+ x[5], 9)
            x[1] ^= rotate(x[13] &+ x[9], 13);  x[5] ^= rotate(x[1] &+ x[13], 18)
